pub struct BackpressureScheduler {
    plans: Vec<Plan>,
}

impl BackpressureScheduler {
    // Create a new backpressure_scheduler with an empty plans vector
    pub fn new() -> Self {
        BackpressureScheduler { plans: Vec::new() }
    }

    // Schedule a new plan
    pub fn schedule(&mut self, plan: Plan) {
        self.plans.push(plan);
    }

    // Run all scheduled plans
    pub fn run(&mut self) {
        for plan in &self.plans {
            plan.action();
        }
        self.plans.clear();
    }
}
